dashboard.definition:
{
    "dataSources": {
        "ds_last_run": {
            "type": "ds.search",
            "options": {"query": "index=_internal sourcetype=splunkd component=ModularInputs \"cveicu\" earliest=-7d@d latest=now\n| head 1\n| eval last_run=strftime(_time, \"%Y-%m-%d %H:%M:%S\")\n| table last_run"}
        },
        "ds_error_count": {
            "type": "ds.search",
            "options": {"query": "index=_internal sourcetype=splunkd severity=ERROR \"TA-cveicu\" earliest=-24h@h latest=now\n| stats count as error_count"}
        },
        "ds_events_ingested": {
            "type": "ds.search",
            "options": {"query": "| inputlookup cve_total.csv\n| table total_cves last_updated\n| eval last_updated=strftime(last_updated, \"%Y-%m-%d %H:%M:%S\")"}
        },
        "ds_checkpoint_state": {
            "type": "ds.search",
            "options": {"query": "`cveicu_index` sourcetype=\"cveicu:audit\" earliest=-7d@d latest=now\n| sort - _time\n| head 5\n| spath message\n| table _time message"}
        },
        "ds_enrichment_freshness": {
            "type": "ds.search",
            "options": {"query": "| inputlookup epss_lookup.csv | stats count as epss_rows\n| appendcols [| inputlookup kev_lookup.csv | stats count as kev_rows]\n| appendcols [| inputlookup risk_priority_lookup.csv | stats count as risk_rows]\n| table epss_rows kev_rows risk_rows"}
        },
        "ds_daily_volume": {
            "type": "ds.search",
            "options": {"query": "`cveicu_index` sourcetype=\"cveicu:record\"\n| eval _time=strptime(date_published, \"%Y-%m-%dT%H:%M:%S\")\n| where _time > relative_time(now(), \"-7d@d\")\n| timechart span=1d count as events_per_day"}
        },
        "ds_internal_errors": {
            "type": "ds.search",
            "options": {"query": "index=_internal sourcetype=splunkd (severity=ERROR OR severity=WARN) \"TA-cveicu\" OR \"cveicu\" earliest=-24h@h latest=now\n| table _time severity message\n| sort - _time\n| head 20"}
        }
    },
    "layout": {
        "type": "grid",
        "options": {"width": 1440},
        "structure": [
            {"item": "viz_last_run", "type": "block", "position": {"x": 0, "y": 0, "w": 480, "h": 120}},
            {"item": "viz_events_ingested", "type": "block", "position": {"x": 480, "y": 0, "w": 480, "h": 120}},
            {"item": "viz_error_count", "type": "block", "position": {"x": 960, "y": 0, "w": 480, "h": 120}},
            {"item": "viz_enrichment", "type": "block", "position": {"x": 0, "y": 120, "w": 720, "h": 200}},
            {"item": "viz_checkpoint", "type": "block", "position": {"x": 720, "y": 120, "w": 720, "h": 200}},
            {"item": "viz_daily_volume", "type": "block", "position": {"x": 0, "y": 320, "w": 1440, "h": 250}},
            {"item": "viz_errors_table", "type": "block", "position": {"x": 0, "y": 570, "w": 1440, "h": 300}}
        ]
    },
    "visualizations": {
        "viz_last_run": {"type": "splunk.singlevalue", "dataSources": {"primary": "ds_last_run"}, "title": "Last Successful Run"},
        "viz_events_ingested": {"type": "splunk.singlevalue", "dataSources": {"primary": "ds_events_ingested"}, "title": "Total Events Ingested"},
        "viz_error_count": {"type": "splunk.singlevalue", "dataSources": {"primary": "ds_error_count"}, "title": "Errors (Last 24h)", "options": {"majorColor": "#dc4e41"}},
        "viz_enrichment": {"type": "splunk.table", "dataSources": {"primary": "ds_enrichment_freshness"}, "title": "Enrichment Lookup Sizes"},
        "viz_checkpoint": {"type": "splunk.table", "dataSources": {"primary": "ds_checkpoint_state"}, "title": "Recent Audit Events"},
        "viz_daily_volume": {"type": "splunk.column", "dataSources": {"primary": "ds_daily_volume"}, "title": "CVEs Published Per Day (Last 7 Days)"},
        "viz_errors_table": {"type": "splunk.table", "dataSources": {"primary": "ds_internal_errors"}, "title": "Recent Errors and Warnings"}
    },
    "title": "Operational Health",
    "description": "TA-cveicu add-on operational status and diagnostics"
}
